        new("07.01.12", "", "Cateterismo de corazón para colocación de marcapaso transitorio (incluido cirujano y cardiólogo, excluido el radiólogo)", 119.25m, 1, 30m, null, 220m, null, null),
        new("07.01.13", "N", "Biopsia de endocardio por cateterismo cardíaco", null, null, null, null, null, null, null),
        new("07.01.14", "N", "Biopsia de miocardio por cateterismo cardíaco", null, null, null, null, null, null, null),
        new("07.01.15", "N", "Colocación de desfibrilador implantable", null, null, null, null, null, null, "Código agregado por el P.M.O. con determinación de cobertura según el P.M.O.E. Obligación de cobertura en los siguientes casos (amplio consenso y evidencia de buena calidad): 1. Prevención secundaria: pacientes que presenten lo siguiente en ausencia de una causa tratable: a) paro cardíaco debido a taquicardia ventricular o fibrilación ventricular; b) taquicardia ventricular (TV) espontánea y sostenida que provoca síncope o compromiso hemodinámico significativo; c) TV sostenida sin síncope o paro cardíaco, asociada a una reducción de la fracción de eyección (<35%) en pacientes cuya clase funcional no sea peor que III de la clasificación funcional de insuficiencia cardíaca de la New York Heart Association. 2. Prevención primaria: a) pacientes con historia de infarto agudo de miocardio (IAM) que a su vez tiene todo lo siguiente: TV no sostenida en el Holter más taquicardia ventricular en estudio electrofisiológico sumado a mala función ventricular izquierda y clase funcional I, II ó III de la clasificación funcional de insuficiencia cardíaca de la New York Heart Association; b) condiciones familiares cardíacas con un alto riesgo de muerte súbita, incluyendo a los síndromes de QT prolongado, la cardiomiopatía hipertrófica, el síndrome de Brugada, la displasia ventricular derecha arritmogénica y luego de la reparación de la tetralogía de Fallot."),
        new("07.02.01", "", "Tratamiento quirúrgico de las cardiopatías congénitas complejas - Tetralogía de Fallot, transposición de los grandes vasos, canales auriculoventriculares comunes, ventrículo único, atresia tricuspídea, enfermedad de Ebstein, etc.", 1806.75m, 3, 361.50m, 399m, 1273m, null, "El PDF imprime 1.086,75 U para el especialista, pero el importe ($420,25) y el total corresponden a 1.806,75 U."),
        new("07.02.02", "E", "Tratamiento quirúrgico de las cardiopatías congénitas complejas con hipotermia profunda. Operación de Rastelli", 1913.25m, 3, 382.50m, 558m, 1642m, null, "El PDF imprime 1.594,50 U para el especialista, pero el importe ($445,02) y el total corresponden a 1.913,25 U."),
        new("07.02.03", "", "Reemplazo de válvula cardíaca por prótesis o injerto", 1594.50m, 3, 318.75m, 451.50m, 1273m, null, null),
        new("07.02.04", "", "Doble reemplazo valvular cardíaco", 1913.25m, 3, 382.50m, 558m, 1273m, null, null),
