        new("15.01.07", "", "Citología exfoliativa hormonal, cada 4 extendidos", 21.75m, null, null, null, 4m, "GASTO_BIOQ", null),
        new("15.01.08", "", "Necropsia de neonato o lactante. Con autorización previa de la Obra Social", 212.25m, null, null, null, 74m, "GASTO_BIOQ", null),
