        new("17.01.09", "", "Monitoraje operatorio (incluye el control osciloscópico, marcapaso externo, desfibrilador, respiración con presión positiva)", 25.50m, null, null, null, 90m, "OTROS_GASTOS", "NORMA: El monitoraje operatorio se podrá efectuar únicamente en pacientes con gran riesgo quirúrgico, debiéndose adjuntar Historia Clínica que justifique su realización y orden del médico cardiólogo."),
        new("17.01.10", "", "Cardioversión en pacientes no internados en sala de terapia intensiva (no en U.T.I.)", 7.50m, null, null, null, 20m, "OTROS_GASTOS", "En el PDF el gasto figura como \"gb\", pero el importe ($2,45) corresponde a otros gastos."),
        new("17.01.11", "", "Ergometría", 15m, null, null, null, 60m, "OTROS_GASTOS", "NORMA: La ergometría y cicloergometría o prueba ergométrica graduada requiere ergómetros electrónicos o mecánicos, sistema de monitorización cardíaca, marcapasos y desfibrilador. Este arancel incluye el monitoreo y los trazados electrocardiográficos necesarios."),
