        new("34.20.12", "N", "R.M.N. de otras regiones encefálicas", null, null, null, null, null, null, "Obligación de cobertura en los siguientes casos: en caso de lesión orgánica (tumores cerebrales, malformaciones)."),
        new("34.20.13", "N", "R.M.N. de columna", null, null, null, null, null, null, "Obligación de cobertura en los siguientes casos: postoperatorio de columna; sospecha de hernia discal recurrente postquirúrgica; ciática y estenosis del canal lumbar; radiculopatía cervical; mielopatía; siringomielia; tumores espinales; tumores de la médula y de la columna; infección; anomalías congénitas; complementa a la ecografía en el período neonatal; trauma; evaluación de la compresión medular (la tomografía es de elección para el traumatismo de columna)."),
        new("34.20.14", "N", "Resonancia magnética nuclear de articulaciones", null, null, null, null, null, null, "Obligación de cobertura en los siguientes casos: patología de rodilla: 1. Pacientes con lesión traumática aguda, subaguda o crónica con sospecha de compromiso de menisco o ligamentos. 2. Pacientes con síntomas internos compatibles con lesiones meniscales o ligamentarias sin antecedentes de traumatismo previo, de por lo menos 2 meses de evolución, como paso previo al estudio artroscópico."),
