        new("43.01.01", "", "Cama en habitación con baño", null, null, null, null, 57m, "PENSION_SANATORIAL", "NORMA: Incluye: uso de cama, ropa limpia, higienización del paciente, limpieza del ambiente, alimentación y los medios necesarios para brindarle un ambiente confortable al paciente. Ambiente climatizado. Personal: incluye asistencia del médico de guardia interno, atención de las enfermeras y mucamas del piso. Excluye: las consultas especializadas. Prácticas incluidas: las nebulizaciones y los gastos correspondientes a las punciones identificadas con los códigos 01.03.07/09, 05.04.08 y 08.02.12 cuando los mismos se realicen durante la internación. Facturación: el día de ingreso se facturará con arancel completo independientemente de la hora en que se haya producido, con la excepción del alta por fallecimiento luego de las 11 horas, o cuando el alta a cargo de la Obra Social, que debió ser informada con la debida antelación, se efectivice después de las 11 horas. La Obra Social tendrá derecho a solicitar protocolo sanatorial del período de internación."),
        new("43.01.02", "E", "Una cama en habitación de dos con baño intermedio", null, null, null, null, 43m, "PENSION_SANATORIAL", "NORMA: Ídem al código 43.01.01."),
        new("43.01.03", "E", "Una cama en habitación de tres con baño incluido", null, null, null, null, 38m, "PENSION_SANATORIAL", "NORMA: Ídem al código 43.01.01."),
        new("43.01.04", "E", "Una cama en habitación de más de tres con baño incluido", null, null, null, null, 34m, "PENSION_SANATORIAL", "NORMA: Ídem al código 43.01.01."),
        new("43.01.05", "", "Atención del recién nacido en habitación y/o nursery", null, null, null, null, 23m, "PENSION_SANATORIAL", "NORMA: A- Atención del recién nacido sano en habitación materna (AMSHM): esta prestación propende a que la atención del recién nacido, al realizarse al lado de la madre, genere una mejor comunicación de esta con el médico y la enfermera, desarrollando los conocimientos de puericultura necesarios. Comprende: uso de cuna, limpieza del ambiente, asistencia por personal especializado, cuidado del recién nacido (control de peso, respiración, vigilancia de nutrición), cambio de ropa e higienización, alimentos especiales y/o artificiales. La habitación debe permitir una adecuada circulación, disponer de lavabo y estar destinada a obstetricia o ginecología no infectada. Asimismo debe cumplimentarse hoja de control con signos de alarma. B- Nursery: ídem segundo párrafo \"Comprende\" más ambiente climatizado."),
        new("43.01.06", "", "Cama para acompañante", null, null, null, null, 68m, "PENSION_SANATORIAL", "Obligación de cobertura en los siguientes casos: internación en menores de 15 años, a fin de asegurar una adecuada contención por parte de un familiar durante un momento crítico como es la internación y sobre todo en este grupo de personas. (En el PDF figuran tachados —suspendidos por el P.M.O. de Emergencia— la mención \"en habitación de dos camas con baño privado\", el párrafo \"Incluye: uso de cama, ropa de cama y desayuno...\" y la ampliación de la norma sobre terapia intensiva.)"),
        new("43.01.07", "E", "Una cama para acompañante en habitación de dos camas con baño intermedio", null, null, null, null, 47m, "PENSION_SANATORIAL", "NORMA: Ídem al código 43.01.06."),
        new("43.01.08", "E", "Una cama para acompañante en habitación de tres camas con baño incluido", null, null, null, null, 41m, "PENSION_SANATORIAL", "NORMA: Ídem al código 43.01.06."),
