        new("OD.01.01", "N", "Consulta. Diagnóstico. Fichado y plan de tratamiento (P.M.O. 1.01)", null, null, null, null, null, null, "Este código incluye examen, diagnóstico y plan de tratamiento. Se considera como primera consulta y comprende la confección de la ficha odontológica."),
        new("OD.01.04", "N", "Consulta de urgencia (P.M.O. 1.04)", null, null, null, null, null, null, "Se considera consulta de urgencia a toda consulta sin turno previo, que resuelva la demanda espontánea. El beneficiario una vez resuelta la urgencia podrá consultar a su odontólogo general para iniciar el tratamiento definitivo de la patología que lo afecte. No se contempla dentro de esa consulta la realización de prácticas no cubiertas, a excepción del cementado de puentes y coronas que no requieran de restauración protética."),
        new("OD.02.01", "N", "Obturación de amalgama. Cavidad simple (P.M.O. 2.01)", null, null, null, null, null, null, null),
        new("OD.02.02", "N", "Obturación de amalgama. Cavidad compuesta o compleja (P.M.O. 2.02)", null, null, null, null, null, null, null),
        new("OD.02.04", "N", "Obturación con tornillo en conducto (P.M.O. 2.04)", null, null, null, null, null, null, "Comprende el tratamiento de los tejidos duros del diente para resolver los daños provocados por la caries dental cuando la destrucción coronaria sea mayor que los dos tercios de la distancia intercuspídea. La obturación definitiva debe incluir, en menores de 18 años, el sellado de todas las superficies no tratadas. Será reconocida una única vez por pieza tratada."),
        new("OD.02.05", "N", "Obturación resina autocurado. Cavidad simple (P.M.O. 2.05)", null, null, null, null, null, null, null),
        new("OD.02.06", "N", "Obturación resina autocurado. Cavidad compuesta o compleja (P.M.O. 2.06)", null, null, null, null, null, null, null),
        new("OD.02.08", "N", "Obturación resina fotocurado sector anterior (P.M.O. 2.08)", null, null, null, null, null, null, "Comprende la restauración de las piezas anteriores y vestibular de primeros premolares."),
        new("OD.02.09", "N", "Reconstrucción de ángulo en dientes anteriores (P.M.O. 2.09)", null, null, null, null, null, null, null),
        new("OD.03.01", "N", "Tratamiento endodóntico en unirradiculares (P.M.O. 3.01)", null, null, null, null, null, null, null),
        new("OD.03.02", "N", "Tratamiento endodóntico en multirradiculares (P.M.O. 3.02)", null, null, null, null, null, null, null),
        new("OD.03.05", "N", "Biopulpectomía parcial (P.M.O. 3.05)", null, null, null, null, null, null, null),
        new("OD.03.06", "N", "Necropulpectomía parcial o momificación (P.M.O. 3.06)", null, null, null, null, null, null, "En piezas que por causa técnicamente justificada no se pueda realizar el tratamiento endodóntico convencional."),
        new("OD.05.01", "N", "Tartrectomía y cepillado mecánico (P.M.O. 5.01)", null, null, null, null, null, null, "Esta práctica no incluye el blanqueamiento de piezas dentarias. En pacientes mayores de 18 se cubrirá una vez por año."),
        new("OD.05.02", "N", "Consulta preventiva. Terapias fluoradas (P.M.O. 5.02)", null, null, null, null, null, null, "Incluye tartrectomía y cepillado mecánico, detección y control de la placa bacteriana, enseñanza de técnicas de higiene. Se cubrirá hasta los 18 años y hasta dos veces por año. Comprende aplicación de flúor tópico, barniz y colutorios."),
        new("OD.05.04", "N", "Consulta preventiva. Detección, control de placa bacteriana y enseñanza de técnicas de higiene bucal (P.M.O. 5.04)", null, null, null, null, null, null, "Comprende enseñanza de técnicas de cepillado, uso de elementos de higiene interdentarios, asesoramiento dietético y revelado de placa. Incluye monitoreo anual."),
        new("OD.05.05", "N", "Selladores de surcos, fosas y fisuras (P.M.O. 5.05)", null, null, null, null, null, null, "Esta práctica se reconoce hasta los 15 años en premolares y molares permanentes."),
        new("OD.05.06", "N", "Aplicación de cariostáticos en piezas dentarias permanentes (P.M.O. 5.06)", null, null, null, null, null, null, null),
        new("OD.07.01", "N", "Consultas de motivación (P.M.O. 7.01)", null, null, null, null, null, null, "Se cubrirá hasta los 15 años de edad e incluye la consulta diagnóstica, examen y plan de tratamiento. Comprende hasta tres visitas al consultorio."),
        new("OD.07.02", "N", "Mantenedor de espacio (P.M.O. 7.02)", null, null, null, null, null, null, "Comprende mantenedores de espacios fijos o removibles. Se cubrirá por única vez por pieza dentaria y en pacientes de hasta 8 años inclusive. Se incluye corona o banda y ansa de alambre de apoyo o tornillo de expansión."),
        new("OD.07.03", "N", "Reducción de luxación con inmovilización dentaria (P.M.O. 7.03)", null, null, null, null, null, null, null),
        new("OD.07.04", "N", "Tratamientos en dientes temporarios con formocresol (P.M.O. 7.04)", null, null, null, null, null, null, "Cuando el diente tratado no esté próximo a su exfoliación. También se cubrirá en piezas permanentes con gran destrucción coronaria."),
        new("OD.07.05", "N", "Corona de acero provisoria por destrucción coronaria (P.M.O. 7.05)", null, null, null, null, null, null, "Se cubrirá en piezas temporarias con tratamiento de formocresol o gran destrucción coronaria, cuando la pieza no se encuentre dentro del período de exfoliación. En primeros molares permanentes hasta los 15 años de edad."),
        new("OD.07.06", "N", "Reimplante dentario e inmovilización por luxación total (P.M.O. 7.06)", null, null, null, null, null, null, null),
        new("OD.07.07", "N", "Protección pulpar directa (P.M.O. 7.07)", null, null, null, null, null, null, null),
        new("OD.08.01", "N", "Consulta de estudio. Sondaje, fichado, diagnóstico y pronóstico (P.M.O. 8.01)", null, null, null, null, null, null, null),
        new("OD.08.02", "N", "Tratamiento de gingivitis (P.M.O. 8.02)", null, null, null, null, null, null, "Comprende tartrectomía, raspaje y alisado, detección y control de placa, topicación con flúor y enseñanza de técnicas de higiene bucal. Se cubrirá anualmente."),
        new("OD.08.03", "N", "Tratamiento de enfermedad periodontal (P.M.O. 8.03)", null, null, null, null, null, null, "Comprende todos los cuadros periodontales e incluye raspaje y alisado radicular. Se cubrirá cada dos años."),
